def C(title, pages, central, adjacent, examples, explain, intro, app):
    """central=(المفهوم، تعريفه)؛ adjacent=[(مفهوم، تعريف)]؛ examples=[(مفهوم، مثال)]؛ explain=[أسطر من شرح الكتاب]"""
    names = [central[0]] + [a[0] for a in adjacent]
    board = [
        {"h": "المفهوم المركزي", "lines": [f"{central[0]}: {central[1]}"]},
        {"h": "المفاهيم المجاورة", "lines": [], "table": [["المفهوم", "تعريفه"]] + [list(a) for a in adjacent]},
        {"h": "شرح وتحليل", "lines": explain},
        {"h": "التمثيل للمفاهيم", "lines": [], "table": [["المفهوم", "مثال"]] + [list(e) for e in examples]},
    ]
    return {"title": title, "match": [title], "pages": pages,
            "objectives": [f"أن يعرّف الطالب مفهوم «{central[0]}» ويحدد دلالته.",
                           "أن يميز المفاهيم المجاورة: " + "، ".join(a[0] for a in adjacent) + ".",
                           "أن يمثل لكل مفهوم ويوظفه في تحليل نص فلسفي."],
            "intro": intro,
            "summary": f"{central[0]}: {central[1]} " + " ".join(explain) + " ومن المفاهيم المجاورة: " + "؛ ".join(f"{a[0]}: {a[1]}" for a in adjacent),
            "points": [f"{central[0]}: {central[1]}"] + [f"{a[0]}: {a[1]}" for a in adjacent],
            "application": {"q": app[0], "a": app[1]}, "board": board}

